-- Unpaid invoice availability is a projection of editor leases, not a new status.
do $$
declare w text:='synthetic-order-edit'; e uuid:='84000000-0000-4000-8000-000000000001'; chart uuid:='85000000-0000-4000-8000-000000000001';
 actor uuid:='81000000-0000-4000-8000-000000000001'; performer uuid:='81000000-0000-4000-8000-000000000003';
 o uuid:='86000000-0000-4000-8000-000000000001'; o2 uuid:='86000000-0000-4000-8000-000000000002';
 wi uuid:='88000000-0000-4000-8000-000000000001'; inv uuid; session uuid:=gen_random_uuid(); second_session uuid:=gen_random_uuid();
 result jsonb; context jsonb; command jsonb; invoice_before jsonb; token timestamptz; checkout uuid; change jsonb; action text;
begin
 perform set_config('request.jwt.claim.sub',performer::text,true);
 result:=public.clair_get_fulfillment_instruction(w,wi);
 perform public.clair_mutate_fulfillment_instruction(w,wi,jsonb_build_object('action','complete_all','commandId',gen_random_uuid(),'expectedRevision',result->>'revision'));
 perform set_config('request.jwt.claim.sub',actor::text,true);
 result:=public.clair_request_selected_chart_order_billing(w,actor,e,public.clair_get_chart_order_billing_summary(w,e)->>'etag','billing-hold',array[o,o2],true);
 inv:=(result->>'invoiceId')::uuid;
 perform public.clair_change_billing_assignment(w,inv,'claim',0);
 perform public.clair_prepare_billing_checkout_session(w,actor,array[inv],'cash');
 select id into checkout from public.billing_checkout_sessions where workspace_id=w and status='prepared';
 select to_jsonb(i),updated_at into invoice_before,token from public.invoices i where id=inv;
 result:=public.clair_manage_confirmed_order_edit_session(w,chart,o,session,'begin');
 context:=result->'context';
 perform pg_temp.assert_true(result->>'editSessionId'=session::text,'completed clinical work still holds unpaid invoice');
 perform pg_temp.assert_true((select to_jsonb(i)=invoice_before from public.invoices i where id=inv),'hold leaves money, status, owner and version unchanged');
 perform pg_temp.assert_true((select status='expired' from public.billing_checkout_sessions where id=checkout),'prepared checkout expired at edit begin');
 perform pg_temp.assert_true((public.clair_get_billing_assignment(w,inv))->>'pauseReason'='order_edit','detail reads hold');
 perform pg_temp.assert_true(exists(select 1 from jsonb_array_elements(public.clair_list_billing_queue(w,(now() at time zone 'Asia/Seoul')::date)) q where q#>>'{invoice,id}'=inv::text and q->>'pauseReason'='order_edit'),'queue reads hold');
 perform pg_temp.assert_true((public.clair_manage_confirmed_order_edit_session(w,chart,o,session,'renew'))->>'editSessionId'=session::text,'billing-only session renews');
 begin perform public.clair_prepare_billing_checkout_session(w,actor,array[inv],'cash'); raise exception 'held prepare accepted';
 exception when raise_exception then if sqlerrm<>'order_work_on_hold' then raise; end if; end;
 begin perform public.clair_transition_billing_invoice_status(w,actor,inv,'paid','cash','Synthetic',token); raise exception 'held payment accepted';
 exception when raise_exception then if sqlerrm<>'order_work_on_hold' then raise; end if; end;
 begin perform public.clair_save_billing_payment_status(w,actor,inv,'complete_payment','cash',null,token); raise exception 'held fallback accepted';
 exception when raise_exception then if sqlerrm<>'order_work_on_hold' then raise; end if; end;
 begin update public.invoices set status='paid' where id=inv; raise exception 'direct paid accepted';
 exception when raise_exception then if sqlerrm<>'order_work_on_hold' then raise; end if; end;
 begin update public.billing_checkout_sessions set status='payment_pending' where id=checkout; raise exception 'direct checkout accepted';
 exception when raise_exception then if sqlerrm<>'order_work_on_hold' then raise; end if; end;
 command:=jsonb_build_object('orderId',o,'chartId',chart,'commandId',gen_random_uuid(),'expectedVersion',context->>'version','editSessionId',session,'financial',jsonb_build_object('unitPriceKrw',7000),'reason','');
 begin perform public.clair_edit_confirmed_order(w,chart,o,command-'editSessionId'); raise exception 'missing lease accepted';
 exception when raise_exception then if sqlerrm<>'order_work_on_hold' then raise; end if; end;
 begin perform public.clair_edit_confirmed_order(w,chart,o,jsonb_set(command,'{expectedVersion}','"stale"')); raise exception 'stale save accepted';
 exception when raise_exception then if sqlerrm<>'revision_conflict' then raise; end if; end;
 perform pg_temp.assert_true(private.clair_invoice_order_edit_held(w,inv),'failed save retains lease');
 begin
  perform public.clair_edit_confirmed_order(w,chart,o,(command-'financial')||jsonb_build_object('reason','x','clinical',jsonb_build_object(
    'detailInputs',(context->'detailInputs')||'{"instruction":"Synthetic changed instruction"}'::jsonb,
    'actualDispenseMode',context->'actualDispenseMode','actualDispenseQuantity',context->'actualDispenseQuantity')));
  raise exception 'post-release validation accepted';
 exception when raise_exception then if sqlerrm<>'invalid_input' then raise; end if; end;
 perform pg_temp.assert_true(private.clair_invoice_order_edit_held(w,inv),'failed validation rolls back lease removal');
 perform public.clair_manage_confirmed_order_edit_session(w,chart,o,gen_random_uuid(),'release');
 perform pg_temp.assert_true(private.clair_invoice_order_edit_held(w,inv),'wrong session cannot release');
 perform public.clair_manage_confirmed_order_edit_session(w,chart,o2,second_session,'begin');
 perform public.clair_manage_confirmed_order_edit_session(w,chart,o,session,'release');
 perform pg_temp.assert_true(private.clair_invoice_order_edit_held(w,inv),'other order retains same invoice hold');
 perform public.clair_manage_confirmed_order_edit_session(w,chart,o2,second_session,'release');
 perform pg_temp.assert_true(not private.clair_invoice_order_edit_held(w,inv),'cancel releases last hold');
 result:=public.clair_manage_confirmed_order_edit_session(w,chart,o,session,'begin');
 command:=jsonb_build_object('orderId',o,'chartId',chart,'commandId',gen_random_uuid(),'expectedVersion',result#>>'{context,version}','editSessionId',session,'reason','');
 perform public.clair_edit_confirmed_order(w,chart,o,command);
 perform pg_temp.assert_true(not private.clair_invoice_order_edit_held(w,inv),'no-change save releases hold');
 result:=public.clair_manage_confirmed_order_edit_session(w,chart,o,session,'begin');
 command:=command||jsonb_build_object('commandId',gen_random_uuid(),'expectedVersion',result#>>'{context,version}','financial',jsonb_build_object('unitPriceKrw',7000));
 perform public.clair_edit_confirmed_order(w,chart,o,command);
 perform pg_temp.assert_true(not private.clair_invoice_order_edit_held(w,inv),'financial save releases edit hold');
 change:=public.clair_get_order_billing_changes(w,inv)->0;
 perform pg_temp.assert_true(change is not null and (select total_amount=(invoice_before->>'total_amount')::numeric from public.invoices where id=inv),'financial proposal still pending without amount change');
 begin perform public.clair_prepare_billing_checkout_session(w,actor,array[inv],'cash'); raise exception 'unapproved financial proposal accepted';
 exception when raise_exception then if sqlerrm not in ('billing_review_required','billing_change_pending') then raise; end if; end;
 result:=public.clair_manage_confirmed_order_edit_session(w,chart,o2,second_session,'begin');
 begin perform public.clair_approve_order_billing_change(w,inv,o,(change->>'proposalId')::uuid,(change->>'version')::integer); raise exception 'approval during another edit accepted';
 exception when raise_exception then if sqlerrm<>'order_work_on_hold' then raise; end if; end;
 update private.order_billing_edit_leases set expires_at=clock_timestamp()-interval '1 second' where session_id=second_session;
 perform pg_temp.assert_true(not private.clair_invoice_order_edit_held(w,inv),'abandoned billing lease expires');
 begin perform public.clair_manage_confirmed_order_edit_session(w,chart,o2,second_session,'renew'); raise exception 'expired renewal accepted';
 exception when raise_exception then if sqlerrm<>'order_edit_session_expired' then raise; end if; end;
 perform public.clair_approve_order_billing_change(w,inv,o,(change->>'proposalId')::uuid,(change->>'version')::integer);
 perform public.clair_prepare_billing_checkout_session(w,actor,array[inv],'cash');
 select id into checkout from public.billing_checkout_sessions where workspace_id=w and status='prepared';
 update public.billing_checkout_sessions set status='payment_pending' where id=checkout;
 result:=public.clair_manage_confirmed_order_edit_session(w,chart,o,gen_random_uuid(),'begin');
 perform pg_temp.assert_true(result->>'editSessionId' is null and not private.clair_invoice_order_edit_held(w,inv),'pending payment excluded from new billing hold');
 raise notice 'PASS billing hold, lease release, expiry, pending proposal, prepared expiry and payment guards';
end $$;
rollback;
